# LeetCode judges this problem via MySQL procedures only.
# Python equivalent for illustration:
def pivot_products(rows):
    # rows: list of (product_id, store, price)
    stores = sorted({s for _, s, _ in rows})
    products = {}
    for pid, s, p in rows:
        products.setdefault(pid, {})[s] = p
    result = []
    for pid in products:
        row = {'product_id': pid}
        for s in stores:
            row[s] = products[pid].get(s)  # None if absent
        result.append(row)
    return result

