// This Database problem is judged as a MySQL stored procedure.
// C++ equivalent sketch of the same dynamic-pivot idea:
#include <map>
#include <set>
#include <string>
#include <vector>
struct Row { int product_id; std::string store; int price; };
std::vector<std::map<std::string, int>> pivot(const std::vector<Row>& rows) {
    std::set<std::string> stores;
    std::map<int, std::map<std::string, int>> byProduct;
    for (auto& r : rows) {
        stores.insert(r.store);
        byProduct[r.product_id][r.store] = r.price;
    }
    std::vector<std::map<std::string, int>> out;
    for (auto& [pid, m] : byProduct) {
        std::map<std::string, int> row{{"product_id", pid}};
        for (auto& s : stores)
            if (m.count(s)) row[s] = m[s]; // absent => NULL
        out.push_back(row);
    }
    return out;
}

