-- This Database problem is judged as a MySQL stored procedure:
CREATE PROCEDURE PivotProducts()
BEGIN
    SET SESSION group_concat_max_len = 1000000;
    SET @sql = NULL;
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MAX(CASE WHEN store = ''', store,
            ''' THEN price END) AS `', store, '`'
        ) ORDER BY store SEPARATOR ', '
    ) INTO @sql
    FROM Products;
    SET @sql = CONCAT(
        'CREATE OR REPLACE VIEW PivotProductsView AS ',
        'SELECT product_id, ', @sql,
        ' FROM Products GROUP BY product_id'
    );
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
END

