// This Database problem is judged as a MySQL stored procedure.
// JavaScript equivalent sketch:
function pivotProducts(rows) {
    const stores = [...new Set(rows.map(r => r.store))].sort();
    const byProduct = new Map();
    for (const {product_id, store, price} of rows) {
        if (!byProduct.has(product_id)) byProduct.set(product_id, {});
        byProduct.get(product_id)[store] = price;
    }
    return [...byProduct.entries()].map(([pid, prices]) => {
        const row = {product_id: pid};
        for (const s of stores) row[s] = s in prices ? prices[s] : null;
        return row;
    });
}
